import type { Sitemap } from "@xos/ia";

/**
 * Pure generation for the console (Section 3.15: navigation is generated from ia/sitemap.yaml). The sitemap becomes
 * a TypeScript module so the proxy and pages read it without parsing YAML at runtime. `test/routes.test.ts`
 * regenerates it in memory and fails on any difference, so a hand edit or a stale file breaks the build.
 */
export const GENERATED_STAMP =
  "// Generated by `pnpm --filter @xos/console generate:sitemap` from ia/sitemap.yaml. Do not edit.";

export function sitemapSource(sitemap: Sitemap): string {
  return `${GENERATED_STAMP}
import type { Sitemap } from "@xos/ia";

/** The console sitemap as data, so the proxy and pages read it without parsing YAML at runtime. */
export const sitemap: Sitemap = ${JSON.stringify(sitemap)};
`;
}
